# Lists the overload sets of the interpreter's library in which, at one position,
# one declaration has a type that fixes no type for a numeral and another has a
# number type. A reading of declaration headers by pattern, not a parse.
import re, sys, glob, collections
NUM = {'ZZ32','ZZ64','NN32','NN64','ZZ','QQ','RR32','RR64','ℤ32','ℤ64','ℕ32','ℕ64','ℤ','ℚ','ℝ32','ℝ64'}
