def split_params(s):
    out, depth, cur = [], 0, ''
    for ch in s:
        if ch in '([{': depth += 1
        if ch in ')]}': depth -= 1
        if ch == ',' and depth == 0: out.append(cur); cur = ''
        else: cur += ch
    if cur.strip(): out.append(cur)
    return [p.strip() for p in out]
for f in files:
    owner = None; tparams = set()
    for ln, line in enumerate(open(f, encoding='utf-8'), 1):
        m = re.match(r'^\s*(?:value\s+)?(?:trait|object)\s+(\w+)', line)
        if m and not line.lstrip().startswith('(*'):
            owner = m.group(1)
        if re.match(r'^end\b', line): owner = None
        m = re.match(r'^(\s*)(?:abstract\s+|private\s+|override\s+)*(opr\s+\S+?|\w+)(\[\\.*?\\\])?\(([^()]*(?:\([^()]*\)[^()]*)*)\)\s*(?::|=|$)', line)
        if not m: continue
        indent, name, sp, params = m.groups()
        if name in ('getter','setter','coerce','if','while','for','assert','println','print','trait','object','end','typecase','case','do','test','property'): continue
        if indent == '' : own = None
        else: own = owner
        ps = split_params(params)
        if not ps: continue
        unb = set()
        if sp:
            for q in split_params(sp[2:-2]):
                q = q.strip()
                if re.match(r'^\w+$', q): unb.add(q)
        types = []
        hasself = False
        for p in ps:
            if p == 'self': types.append(own or '?self'); hasself = True
            elif ':' in p: types.append(p.split(':',1)[1].strip().rstrip('.').strip())
            else: types.append('_untyped')
