        for i, catch, nums in hits:
            print('  position %d: unfixed in %d (%s); number types: %s' % (
                i, len(catch), '; '.join(sorted({c[2]+' '+c[0][i] for c in catch}))[:300],
                ', '.join(sorted({d[0][i] for d in nums}))))
